-- Big change: the pets speak as pets. Human archetypes (Tia, Nortenho, Karen...)
-- are retired (kept inactive, so old generations still resolve them).
-- 8 universal animal moods, the same in every language; the AI adapts the
-- joke to whether the photo shows a cat or a dog.

update public.personalities set active = false;

on conflict (id) do update set
  language = excluded.language, name = excluded.name, tagline = excluded.tagline,
  voice_prompt = excluded.voice_prompt, image_prompt = excluded.image_prompt,
  sort_order = excluded.sort_order, markets = excluded.markets, active = true;
